def t(key: str, lang: str, **kw: object) -> str:
    entry = TEXTS.get(key)
    if entry is None:
        return key
    s = entry.get(lang) or entry["en"]
    return s.format(**kw) if kw else s


@lru_cache(maxsize=1)
def load_questions(path: str | None = None) -> dict:
    p = Path(path) if path else DATA_DIR / "questions.yaml"
    with open(p, encoding="utf-8") as fh:
        data = yaml.safe_load(fh)
    return data


def questions_for_step(step: int) -> list[dict]:
    return [q for q in load_questions()["questions"] if q["step"] == step]


def question_by_id(qid: str) -> dict:
    for q in load_questions()["questions"]:
        if q["id"] == qid:
            return q
    raise KeyError(qid)


def qlabel(q: dict, lang: str) -> str:
    return q.get(f"label_{lang}") or q["label_en"]


def qhelp(q: dict, lang: str) -> str:
    return q.get(f"help_{lang}") or q.get("help_en") or ""


def olabel(o: dict, lang: str) -> str:
    return o.get(f"label_{lang}") or o["label_en"]
